/*
 * Функция flang «Приписать строку в начало».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param pervaya — «первая»: строка
 * @param elementy — «элементы»: список: строка
 * @return значение: список: строка
 */
fl_status kompilyator_flang_pripisat_stroku_v_nachalo(fl_ctx *ctx, fl_value pervaya, fl_value elementy, fl_value *result, fl_error *error) {
  fl_value fl_t1 = fl_nothing(); /* «приписать» */
  FL_TRY(fl_b_pripisat(ctx, pervaya, elementy, &fl_t1, error));
  *result = fl_t1;
  return FL_OK;
}

/*
 * Функция flang «Соединить строки».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param chasti — «части»: список: строка
 * @param razdelitel — «разделитель»: строка
 * @return значение: строка
 */
fl_status kompilyator_flang_soedinit_stroki(fl_ctx *ctx, fl_value chasti, fl_value razdelitel, fl_value *result, fl_error *error) {
  if (fl_chain_empty(chasti)) {
    *result = kompilyator_flang_text_291;
    return FL_OK;
  } else if (fl_chain_cons(chasti)) {
    const fl_value golova = fl_chain_head(chasti); /* голова «голова» */
    const fl_value hvost = fl_chain_tail(chasti); /* хвост «хвост» */
    fl_value fl_t2 = fl_nothing();
    FL_TRY(fl_require_list(ctx, hvost, "свёртка", &fl_t2, error));
    fl_value akk = golova; /* «акк» */
    for (size_t fl_t3 = 0; fl_t3 < fl_t2.as.list.count; fl_t3 += 1) {
      const fl_value chast = fl_t2.as.list.items[fl_t3]; /* «часть» */
      fl_value fl_t4 = fl_nothing();
      FL_TRY(fl_concat(ctx, akk, razdelitel, &fl_t4, error));
      fl_value fl_t5 = fl_nothing();
      FL_TRY(fl_concat(ctx, fl_t4, chast, &fl_t5, error));
      akk = fl_t5;
    }
    *result = akk;
    return FL_OK;
  } else {
    return fl_match_fail(ctx, chasti, error);
  }
}

/*
 * Функция flang «Заменить».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param tekst — «текст»: строка
 * @param chto — «что»: строка
 * @param chem — «чем»: строка
 * @return значение: строка
 */
fl_status kompilyator_flang_zamenit(fl_ctx *ctx, fl_value tekst, fl_value chto, fl_value chem, fl_value *result, fl_error *error) {
  fl_value fl_t6 = fl_nothing(); /* «разделить» */
  FL_TRY(fl_b_razdelit(ctx, tekst, chto, &fl_t6, error));
  return kompilyator_flang_soedinit_stroki(ctx, fl_t6, chem, result, error);
}

/*
 * Функция flang «Позиция подстроки».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 * @param tekst — «текст»: строка
 * @param chast — «часть»: строка
 * @return значение: число
 */
fl_status kompilyator_flang_poziciya_podstroki(fl_ctx *ctx, fl_value tekst, fl_value chast, fl_value *result, fl_error *error) {
  fl_value fl_t7 = fl_nothing(); /* «содержит» */
  FL_TRY(fl_b_soderzhit(ctx, tekst, chast, &fl_t7, error));
  bool fl_t8 = false;
  FL_TRY(fl_cond(ctx, fl_t7, &fl_t8, error));
  if (fl_t8) {
    fl_value fl_t9 = fl_nothing(); /* «разделить» */
    FL_TRY(fl_b_razdelit(ctx, tekst, chast, &fl_t9, error));
    fl_value fl_t10 = fl_nothing(); /* «голова» */
    FL_TRY(fl_b_golova_dokazano(ctx, fl_t9, &fl_t10, error));
    fl_value fl_t11 = fl_nothing(); /* «длина» */
    FL_TRY(fl_b_dlina(ctx, fl_t10, &fl_t11, error));
    if (fl_t11.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "add", fl_t11, fl_number(1.0), error));
    *result = fl_number(fl_t11.as.number + 1.0);
    return FL_OK;
  } else {
    *result = fl_number(0.0);
    return FL_OK;
  }
}

/* Тело «Повторить»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_povtorit_body(fl_ctx *ctx, fl_value tekst, fl_value raz, fl_value *result, fl_error *error) {
  if (raz.tag != FL_NUMBER) FL_TRY(fl_not_order(ctx, raz, fl_number(0.0), error));
  bool fl_t12 = false;
  FL_TRY(fl_cond(ctx, fl_flag(raz.as.number <= 0.0), &fl_t12, error));
  if (fl_t12) {
    *result = kompilyator_flang_text_291;
    return FL_OK;
  } else {
    if (raz.tag != FL_NUMBER) FL_TRY(fl_not_numbers(ctx, "sub", raz, fl_number(1.0), error));
    const fl_value shag = fl_number(raz.as.number - 1.0); /* пусть «шаг» */
    fl_value fl_t13 = fl_nothing();
    FL_TRY(fl_lt(ctx, shag, raz, &fl_t13, error));
    bool fl_t14 = false;
    FL_TRY(fl_cond(ctx, fl_t13, &fl_t14, error));
    fl_value fl_t15 = fl_nothing();
    if (fl_t14) {
      fl_t15 = shag;
    } else {
      fl_value fl_t16 = fl_nothing();
      FL_TRY(kompilyator_flang_mera_ubyvaet(ctx, shag, raz, &fl_t16, error));
      fl_t15 = fl_t16;
    }
    fl_value fl_t17 = fl_nothing();
    FL_TRY(kompilyator_flang_povtorit(ctx, tekst, fl_t15, &fl_t17, error));
    fl_value fl_t18 = fl_nothing();
    FL_TRY(fl_concat(ctx, tekst, fl_t17, &fl_t18, error));
    *result = fl_t18;
    return FL_OK;
  }
}

/*
 * Функция flang «Повторить».
 *
 * Тотальная: завершение доказано анализом завершаемости (totality.mjs).
 *
 * Рекурсивная: считает глубину, на превышении — FLANG_RECURSION_LIMIT.
 * @param tekst — «текст»: строка
 * @param raz — «раз»: число
 * @return значение: строка
 */
fl_status kompilyator_flang_povtorit(fl_ctx *ctx, fl_value tekst, fl_value raz, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Повторить", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_povtorit_body(ctx, tekst, raz, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

