    FL_TRY(kompilyator_flang_kuski_na_poverhnosti(ctx, fl_t1954, poverhnost, fl_flag(false), fl_list(NULL, 0), &fl_t1955, error));
    fl_value fl_t1956 = fl_nothing(); /* «соединить» */
    FL_TRY(fl_b_soedinit(ctx, fl_t1955, kompilyator_flang_text_328, &fl_t1956, error));
    *result = fl_t1956;
    return FL_OK;
