/* Тело «Назвать диспетчеры»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_nazvat_dispetchery_body(fl_ctx *ctx, fl_value arnosti, fl_value zanyatye, fl_value gotovye, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(arnosti)) {
      *result = gotovye;
      return FL_OK;
    } else if (fl_chain_cons(arnosti)) {
      const fl_value golova = fl_chain_head(arnosti); /* голова «голова» */
      const fl_value hvost = fl_chain_tail(arnosti); /* хвост «хвост» */
      fl_value fl_t11324 = fl_nothing();
      FL_TRY(kompilyator_flang_imya_dispetchera(ctx, golova, zanyatye, &fl_t11324, error));
      const fl_value imya = fl_t11324; /* пусть «имя» */
      fl_value fl_t11325 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, imya, zanyatye, &fl_t11325, error));
      fl_value fl_t11327[2];
      fl_t11327[0] = golova; /* «арность» */
      fl_t11327[1] = imya; /* «имя» */
      fl_value fl_t11326 = fl_nothing();
      FL_TRY(fl_record_new(ctx, kompilyator_flang_names_57, fl_t11327, 2, &fl_t11326, error));
      fl_value fl_t11328 = fl_nothing(); /* «добавить» */
      FL_TRY(fl_b_dobavit(ctx, fl_t11326, gotovye, &fl_t11328, error));
      arnosti = hvost;
      zanyatye = fl_t11325;
      gotovye = fl_t11328;
      /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
      FL_TRY(fl_tick(ctx, "Назвать диспетчеры", error));
      continue;
    } else {
      return fl_match_fail(ctx, arnosti, error);
    }
  }
}

