/* Тело «Одинаковые списки типов»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_odinakovye_spiski_tipov_body(fl_ctx *ctx, fl_value pervye, fl_value vtorye, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(pervye)) {
      fl_value fl_t15140 = fl_nothing(); /* «пусто» */
      FL_TRY(fl_b_pusto(ctx, vtorye, &fl_t15140, error));
      *result = fl_t15140;
      return FL_OK;
    } else if (fl_chain_cons(pervye)) {
      const fl_value pervyy = fl_chain_head(pervye); /* голова «первый» */
      const fl_value prochie = fl_chain_tail(pervye); /* хвост «прочие» */
      fl_value fl_t15141 = fl_nothing(); /* «пусто» */
      FL_TRY(fl_b_pusto(ctx, vtorye, &fl_t15141, error));
      bool fl_t15142 = false;
      FL_TRY(fl_cond(ctx, fl_t15141, &fl_t15142, error));
      if (fl_t15142) {
        *result = fl_flag(false);
        return FL_OK;
      } else {
        fl_value fl_t15143 = fl_nothing(); /* «голова» */
        FL_TRY(fl_b_golova_dokazano(ctx, vtorye, &fl_t15143, error));
        fl_value fl_t15144 = fl_nothing();
        FL_TRY(kompilyator_flang_odinakovye_tipy(ctx, pervyy, fl_t15143, &fl_t15144, error));
        bool fl_t15145 = false;
        FL_TRY(fl_cond(ctx, fl_t15144, &fl_t15145, error));
        if (fl_t15145) {
          fl_value fl_t15146 = fl_nothing(); /* «хвост» */
          FL_TRY(fl_b_hvost_dokazano(ctx, vtorye, &fl_t15146, error));
          pervye = prochie;
          vtorye = fl_t15146;
          /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
          FL_TRY(fl_tick(ctx, "Одинаковые списки типов", error));
          continue;
        } else {
          *result = fl_flag(false);
          return FL_OK;
        }
      }
    } else {
      return fl_match_fail(ctx, pervye, error);
    }
  }
}

