/* Тело «Найти описание»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_nayti_opisanie_body(fl_ctx *ctx, fl_value opisaniya, fl_value imya, fl_value *result, fl_error *error) {
  for (;;) {
    if (fl_chain_empty(opisaniya)) {
      fl_value fl_t21071 = fl_nothing();
      FL_TRY(fl_variant_new(ctx, "Нет описания", NULL, NULL, 0, &fl_t21071, error));
      *result = fl_t21071;
      return FL_OK;
    } else if (fl_chain_cons(opisaniya)) {
      const fl_value pervoe = fl_chain_head(opisaniya); /* голова «первое» */
      const fl_value prochie = fl_chain_tail(opisaniya); /* хвост «прочие» */
      fl_value fl_t21072 = fl_nothing();
      FL_TRY(fl_field_get(ctx, pervoe, "имя", &fl_t21072, error));
      bool fl_t21073 = false;
      FL_TRY(fl_cond(ctx, fl_flag(fl_equal(fl_t21072, imya)), &fl_t21073, error));
      if (fl_t21073) {
        fl_value fl_t21075[1];
        fl_t21075[0] = pervoe; /* «описание» */
        fl_value fl_t21074 = fl_nothing();
        FL_TRY(fl_variant_new(ctx, "Есть описание", kompilyator_flang_names_280, fl_t21075, 1, &fl_t21074, error));
        *result = fl_t21074;
        return FL_OK;
      } else {
        const fl_value fl_t21076 = imya;
        opisaniya = prochie;
        imya = fl_t21076;
        /* виток цикла — тоже шаг: незавершающийся самовызов обязан упереться в лимит */
        FL_TRY(fl_tick(ctx, "Найти описание", error));
        continue;
      }
    } else {
      return fl_match_fail(ctx, opisaniya, error);
    }
  }
}

