fl_status kompilyator_flang_nayti_opisanie(fl_ctx *ctx, fl_value opisaniya, fl_value imya, fl_value *result, fl_error *error) {
  FL_TRY(fl_enter(ctx, "Найти описание", error));
  {
    const fl_mark region = fl_region_open(ctx);
    const fl_status status = kompilyator_flang_nayti_opisanie_body(ctx, opisaniya, imya, result, error);
    fl_leave(ctx);
    return fl_region_close(ctx, region, status, result, error);
  }
}

