/* Тело «Замены аргументов вызова»; глубину считает обёртка ниже. */
static fl_status kompilyator_flang_zameny_argumentov_vyzova_body(fl_ctx *ctx, fl_value parametry, fl_value argumenty, fl_value *result, fl_error *error) {
  if (fl_chain_empty(parametry)) {
    *result = fl_list(NULL, 0);
    return FL_OK;
  } else if (fl_chain_cons(parametry)) {
    const fl_value p = fl_chain_head(parametry); /* голова «п» */
    const fl_value hp = fl_chain_tail(parametry); /* хвост «хп» */
    if (fl_chain_empty(argumenty)) {
      *result = fl_list(NULL, 0);
      return FL_OK;
    } else if (fl_chain_cons(argumenty)) {
      const fl_value a = fl_chain_head(argumenty); /* голова «а» */
      const fl_value ha = fl_chain_tail(argumenty); /* хвост «ха» */
      fl_value fl_t26508 = fl_nothing();
      FL_TRY(kompilyator_flang_zameny_argumentov_vyzova(ctx, hp, ha, &fl_t26508, error));
      fl_value fl_t26509 = fl_nothing();
      FL_TRY(kompilyator_flang_stroka_polya(ctx, p, kompilyator_flang_text_344, &fl_t26509, error));
      return kompilyator_flang_polozhit_zamenu(ctx, fl_t26508, fl_t26509, a, result, error);
    } else {
      return fl_match_fail(ctx, argumenty, error);
    }
  } else {
    return fl_match_fail(ctx, parametry, error);
  }
}

